export default function AccountAtmosphere() {
  return (
    <div className="account-atmosphere" aria-hidden="true">
      <span className="account-atmosphere__light account-atmosphere__light--one" />
      <span className="account-atmosphere__light account-atmosphere__light--two" />
      <span className="account-atmosphere__light account-atmosphere__light--three" />
      <span className="account-atmosphere__orb account-atmosphere__orb--one" />
      <span className="account-atmosphere__orb account-atmosphere__orb--two" />
      <span className="account-atmosphere__ring" />
      <span className="account-atmosphere__diamond" />
      <span className="account-atmosphere__grid" />
    </div>
  );
}
